using System;
using System.Diagnostics;

// PROGRAM: Eksperimen Empiris Big O: O(N) vs O(N^2)
const int N = 10_000;
int[] data = new int[N];
for (int i = 0; i < N; i++) data[i] = i;

// 1. Uji Kompleksitas O(N) - Linear Scan
var swLinear = Stopwatch.StartNew();
long counterLinear = 0;
for (int i = 0; i < N; i++)
{
    counterLinear += data[i];
}
swLinear.Stop();
Console.WriteLine($"[O(N) Linear] N={N:N0} selesai dalam: {swLinear.ElapsedMilliseconds} ms ({swLinear.ElapsedTicks} ticks)");

// 2. Uji Kompleksitas O(N^2) - Nested Loop
var swQuad = Stopwatch.StartNew();
long counterQuad = 0;
for (int i = 0; i < N; i++)
{
    for (int j = 0; j < N; j++)
    {
        counterQuad += (data[i] ^ data[j]);
    }
}
swQuad.Stop();
Console.WriteLine($"[O(N^2) Kuadratik] N={N:N0} selesai dalam: {swQuad.ElapsedMilliseconds} ms ({counterQuad})");

