using System;
using System.Collections.Generic;

public class TwoSumFinder
{
    public static int[] FindPairWithSum(int[] numbers, int targetSum)
    {
        if (numbers == null || numbers.Length < 2) return Array.Empty<int>();

        var visited = new HashSet<int>();
        foreach (var n in numbers)
        {
            int complement = targetSum - n;
            if (visited.Contains(complement))
            {
                return new[] { Math.Min(n, complement), Math.Max(n, complement) };
            }
            visited.Add(n);
        }

        return Array.Empty<int>();
    }

    public static void Main()
    {
        int[] data = { 10, 15, 3, 7 };
        var pair = FindPairWithSum(data, 17);
        Console.WriteLine(string.Join(", ", pair));
    }
}
